   821  static bool translateInstruction(MCInst *mcInst, InternalInstruction *insn)
   822  {
   823          int index;
   824
   825          if (!insn->spec) {
   826                  //debug("Instruction has no specification");
   827                  return true;
   828          }
   829
   830          MCInst_clear(mcInst);
   831          MCInst_setOpcode(mcInst, insn->instructionID);
   832
   833          // If when reading the prefix bytes we determined the overlapping 0xf2 or 0xf3
   834          // prefix bytes should be disassembled as xrelease and xacquire then set the
   835          // opcode to those instead of the rep and repne opcodes.
   836  #ifndef CAPSTONE_X86_REDUCE
   837          if (insn->xAcquireRelease) {
   838                  if (MCInst_getOpcode(mcInst) == X86_REP_PREFIX)
   839                          MCInst_setOpcode(mcInst, X86_XRELEASE_PREFIX);
   840                  else if (MCInst_getOpcode(mcInst) == X86_REPNE_PREFIX)
   841                          MCInst_setOpcode(mcInst, X86_XACQUIRE_PREFIX);
   842          }
   843  #endif
   844
   845          insn->numImmediatesTranslated = 0;
   846
   847          for (index = 0; index < X86_MAX_OPERANDS; ++index) {
   848                  if (insn->operands[index].encoding != ENCODING_NONE) {
   849                          if (translateOperand(mcInst, &insn->operands[index], insn)) {
   850                                  return true;
   851                          }
   852                  }
   853          }
   854
   855          return false;
